{
  "spec_version": 1.0,
  "title": "Tính khoảng cách từ trung điểm M của A'C' đến mặt phẳng (ABB'A')",
  "description": "Cho lăng trụ đứng ABC.A'B'C' có đáy ABC vuông tại B với AB = 2, BC = 2 và cạnh bên AA' = 2. Gọi M là trung điểm của A'C'. Tính khoảng cách từ M đến mặt phẳng (ABB'A').",
  "memory_declarations": [
    {
      "name": "A",
      "type": "point3",
      "label": "Điểm A"
    },
    {
      "name": "B",
      "type": "point3",
      "label": "Điểm B"
    },
    {
      "name": "C",
      "type": "point3",
      "label": "Điểm C"
    },
    {
      "name": "A_prime",
      "type": "point3",
      "label": "Điểm A'"
    },
    {
      "name": "B_prime",
      "type": "point3",
      "label": "Điểm B'"
    },
    {
      "name": "C_prime",
      "type": "point3",
      "label": "Điểm C'"
    },
    {
      "name": "M",
      "type": "point3",
      "label": "Trung điểm M của A'C'"
    },
    {
      "name": "P_ABB_prime_A_prime",
      "type": "plane3",
      "label": "Mặt phẳng (ABB'A')"
    },
    {
      "name": "distance_M_to_P",
      "type": "float",
      "label": "Khoảng cách từ M đến (ABB'A')"
    }
  ],
  "statements": [
    {
      "kind": "declare_point",
      "target_var": "A",
      "at": [0, 0, 0],
      "model_assumption": "Đặt gốc tọa độ tại A"
    },
    {
      "kind": "declare_point",
      "target_var": "B",
      "at": [2, 0, 0],
      "source_fact_id": "AB_length",
      "model_assumption": "AB = 2, nằm trên trục Ox"
    },
    {
      "kind": "declare_point",
      "target_var": "C",
      "at": [2, 2, 0],
      "source_fact_id": "BC_length_and_ABC_vuong_B",
      "model_assumption": "BC = 2, vuông góc với AB tại B, song song trục Oy"
    },
    {
      "kind": "declare_point",
      "target_var": "A_prime",
      "at": [0, 0, 2],
      "source_fact_id": "AA_prime_length",
      "model_assumption": "AA' = 2, lăng trụ đứng, nằm trên trục Oz"
    },
    {
      "kind": "declare_point",
      "target_var": "B_prime",
      "at": [2, 0, 2],
      "model_assumption": "Dựng B' từ B và A' theo tính chất lăng trụ đứng"
    },
    {
      "kind": "declare_point",
      "target_var": "C_prime",
      "at": [2, 2, 2],
      "model_assumption": "Dựng C' từ C và A' theo tính chất lăng trụ đứng"
    },
    {
      "kind": "construct_point",
      "target_var": "M",
      "expr": {
        "kind": "midpoint",
        "a": "A_prime",
        "b": "C_prime"
      },
      "label": "M là trung điểm của A'C'"
    },
    {
      "kind": "construct_plane",
      "target_var": "P_ABB_prime_A_prime",
      "through": ["A", "B", "A_prime"],
      "label": "Mặt phẳng (ABB'A')"
    },
    {
      "kind": "assign",
      "target_var": "distance_M_to_P",
      "expr": {
        "kind": "measure",
        "quantity": "distance",
        "of": "M",
        "wrt": "P_ABB_prime_A_prime"
      }
    },
    {
      "kind": "return",
      "val": {
        "kind": "var",
        "name": "distance_M_to_P"
      }
    }
  ],
  "visual_bindings": {
    "containers": [],
    "pointers": [],
    "value_boxes": [
      {
        "box_id": "box_A",
        "var_ref": "A",
        "label": "A"
      },
      {
        "box_id": "box_B",
        "var_ref": "B",
        "label": "B"
      },
      {
        "box_id": "box_C",
        "var_ref": "C",
        "label": "C"
      },
      {
        "box_id": "box_A_prime",
        "var_ref": "A_prime",
        "label": "A'"
      },
      {
        "box_id": "box_B_prime",
        "var_ref": "B_prime",
        "label": "B'"
      },
      {
        "box_id": "box_C_prime",
        "var_ref": "C_prime",
        "label": "C'"
      },
      {
        "box_id": "box_M",
        "var_ref": "M",
        "label": "M"
      },
      {
        "box_id": "box_P_ABB_prime_A_prime",
        "var_ref": "P_ABB_prime_A_prime",
        "label": "(ABB'A')"
      },
      {
        "box_id": "box_distance",
        "var_ref": "distance_M_to_P",
        "label": "Khoảng cách"
      }
    ]
  },
  "pedagogical_intent": "Minh họa cách tính khoảng cách từ một điểm đến một mặt phẳng trong không gian bằng phương pháp tọa độ."
}

